P('a069', 5, 2, 'Summe berechnen', 'summe = 0\nfor i in range(1, <<n>> + 1):\n    summe = summe + i\nprint(summe)', ['Die Schleife läuft von 1 bis n (n + 1 wird nicht mehr erreicht).', 'summe sammelt alle Zahlen auf.'], vars={'n': ['4', '5', '6']})
P('a070', 5, 3, 'range mit Schrittweite', 'for i in range(<<a>>, 0, -<<s>>):\n    print(i)', ['range(start, stop, schritt): Mit negativem Schritt wird rückwärts gezählt.', 'Der Endwert 0 selbst wird nicht erreicht.'], vars={'a': ['10', '12', '9'], 's': ['3', '4', '2']})
P('a071', 5, 3, 'if in der Schleife', 'for i in range(1, 8):\n    if i % 3 == 0:\n        print(i, "Fizz")', ['Der print-Befehl gehört zum if und läuft nur, wenn i durch 3 teilbar ist.'])
