B('a076', 5, 2, 'Endlosschleife', 'Das Programm soll von 5 bis 1 herunterzählen und dann enden.', 'zahl = 5\nwhile zahl > 0:\n    print(zahl)', 'zahl = 5\nwhile zahl > 0:\n    print(zahl)\n    zahl = zahl - 1', ['Die Bedingung zahl > 0 bleibt immer wahr.', 'Die Variable muss in der Schleife verändert werden.'])
B('a077', 5, 3, 'Eins zu wenig', 'Das Programm soll die Summe von 1 bis n berechnen (bei 5 soll 15 herauskommen).', 'n = int(input())\nsumme = 0\nfor i in range(1, n):\n    summe = summe + i\nprint(summe)', 'n = int(input())\nsumme = 0\nfor i in range(1, n + 1):\n    summe = summe + i\nprint(summe)', ['Das letzte n wird nicht mitgezählt.', 'range(1, n) hört vor n auf.'], tests=[['5'], ['10'], ['1']])
Z('a078', 5, 2, 'Countdown mit while', 'Bringe die Zeilen in die richtige Reihenfolge (auf die Einrückung achten).', ['zahl = 3', 'while zahl > 0:', '    print(zahl)', '    zahl = zahl - 1', 'print("Start!")'], ['Die Variable muss vor der Schleife angelegt werden.', 'Das letzte print steht nicht eingerückt – es läuft erst nach der Schleife.'])
