C('a081', 5, 2, 'Einmaleins', 'Gib die ersten zehn Vielfachen von <<n>> untereinander aus (also <<n>>, 2·<<n>>, … bis 10·<<n>>), nur die Ergebnisse.', 'for i in range(1, 11):\n    print(i * <<n>>)', ['Eine Schleife von 1 bis 10 und i * <<n>>.'], vars={'n': ['3', '7', '9']})
C('a082', 5, 2, 'Summe bis n', 'Lies eine Zahl n ein und gib die Summe 1 + 2 + … + n aus. Benutze eine Schleife.', 'n = int(input())\nsumme = 0\nfor i in range(1, n + 1):\n    summe = summe + i\nprint(summe)', ['Lege eine Variable summe mit 0 an.', 'Zähle in der Schleife jede Zahl dazu.'], tests=[['5'], ['10'], ['100']], need=[{'re': '(for|while)\\b', 'msg': 'Benutze eine Schleife (for oder while).'}])
C('a083', 5, 3, 'Teiler', 'Lies eine Zahl n ein und gib alle Teiler von n untereinander aus (von klein nach groß).', 'n = int(input())\nfor i in range(1, n + 1):\n    if n % i == 0:\n        print(i)', ['Prüfe jede Zahl von 1 bis n.', 'i ist ein Teiler, wenn n % i gleich 0 ist.'], tests=[['12'], ['7'], ['20']])
C('a084', 5, 3, 'Sternchen-Dreieck', 'Lies eine Zahl n ein und gib ein Dreieck aus Sternchen aus: In Zeile 1 steht ein `*`, in Zeile 2 stehen zwei `**`, … bis n Sternchen. (Bei n = 3: `*`, `**`, `***`.)', 'n = int(input())\nfor i in range(1, n + 1):\n    print("*" * i)', ['Text lässt sich mit einer Zahl malnehmen: "ab" * 3 ergibt "ababab".'], tests=[['3'], ['5'], ['1']])
